(function () {
  if (document.getElementById("vp")) return;   // the page carries its own markup
  var host = document.createElement("div");
  host.innerHTML = "<div id=\"vp\"><div id=\"scroller\">\r\n\r\n  <header class=\"lab-hero\">\r\n    <div class=\"wrap\">\r\n      <p class=\"mono eyebrow rv\">Component lab &middot; 07 &nbsp;/&nbsp; Scroll</p>\r\n      <h1 class=\"rv\">Every section, its own <span class=\"it\">set-piece</span>.</h1>\r\n      <p class=\"lede rv\">Eight scroll treatments, one per section. All eight share a single rig &mdash;\r\n        a tall section holding a pinned stage that writes one scrubbed value across itself &mdash;\r\n        and everything else is CSS reading that value. Which means all eight run backwards as cleanly\r\n        as forwards, and a ninth is a block of CSS rather than another script.</p>\r\n\r\n      <nav class=\"lab-tabs rv\" style=\"margin-top:34px\" aria-label=\"Component lab\">\r\n        <a class=\"lab-tab\" href=\"/media\"><i></i>Media</a>\r\n        <a class=\"lab-tab\" href=\"/cards\"><i></i>Cards</a>\r\n        <a class=\"lab-tab\" href=\"/testimonials\"><i></i>Testimonials</a>\r\n        <a class=\"lab-tab\" href=\"/cta\"><i></i>Call to action</a>\r\n        <a class=\"lab-tab\" href=\"/team\"><i></i>Team</a>\r\n        <a class=\"lab-tab\" href=\"/backgrounds\"><i></i>Backgrounds</a>\r\n        <a class=\"lab-tab\" href=\"/scroll\" aria-current=\"page\"><i></i>Scroll</a>\r\n      </nav>\r\n\r\n      <div class=\"lab-figs rv\">\r\n        <div class=\"lab-fig\"><b>08</b><em>Set-pieces</em></div>\r\n        <div class=\"lab-fig\"><b>1</b><em>Scrubbed value each</em></div>\r\n        <div class=\"lab-fig\"><b>100%</b><em>Reversible</em></div>\r\n        <div class=\"lab-fig\"><b>0</b><em>Scroll libraries</em></div>\r\n      </div>\r\n    </div>\r\n  </header>\r\n\r\n  <!-- ============ 01 — GRADIENT TEXT ============ -->\r\n  <section class=\"lab-sec\" id=\"gradient\" style=\"padding-bottom:0\">\r\n    <div class=\"wrap\">\r\n      <div class=\"lab-head\">\r\n        <div>\r\n          <p class=\"mono eyebrow rv\">Set-piece 01 &middot; Gradient text</p>\r\n          <h2 class=\"display\" data-split=\"rise\">Read as you scroll.</h2>\r\n        </div>\r\n        <div>\r\n          <p class=\"lede rv\">The sentence is set twice: a dim copy that never moves, and a lit copy\r\n            uncovered from the top a line at a time. The gradient inside the lit copy travels as\r\n            well, so the brightest point stays near the line being read rather than sitting still.</p>\r\n          <ul class=\"spec mono rv\">\r\n            <li>background-clip: text</li><li>clip-path wipe</li>\r\n            <li>Travelling gradient</li><li>Real text underneath</li>\r\n          </ul>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"pin\" data-pin>\r\n      <div class=\"pin-stage\">\r\n        <canvas class=\"pin-bg\" data-bg=\"contour\" data-density=\".8\" data-speed=\".6\" data-alpha=\".55\" aria-hidden=\"true\"></canvas>\r\n        <span class=\"pin-veil\" aria-hidden=\"true\"></span>\r\n        <div class=\"wrap\">\r\n          <div class=\"gt\">\r\n            <p class=\"gt-dim\">Most agencies sell you one discipline and quietly subcontract the\r\n              other two. We run design, search and infrastructure in the same room, which is why\r\n              the handover between them never costs you a month.</p>\r\n            <p class=\"gt-lit\" aria-hidden=\"true\">Most agencies sell you one discipline and quietly\r\n              subcontract the other two. We run design, search and infrastructure in the same room,\r\n              which is why the handover between them never costs you a month.</p>\r\n          </div>\r\n        </div>\r\n        <p class=\"pin-meter\"><span>Reveal</span><span class=\"bar\"><i></i></span><b data-k-out=\"pct\">000</b></p>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- ============ 02 — SPLIT SCREEN ============ -->\r\n  <section class=\"lab-sec\" id=\"split\" style=\"padding-bottom:0\">\r\n    <div class=\"wrap\">\r\n      <div class=\"lab-head\">\r\n        <div>\r\n          <p class=\"mono eyebrow rv\">Set-piece 02 &middot; Split screen</p>\r\n          <h2 class=\"display\" data-split=\"rise\">The word comes apart.</h2>\r\n        </div>\r\n        <div>\r\n          <p class=\"lede rv\">One word, drawn twice at exactly the same place, with each half of the\r\n            screen clipping its own half of it. As the two panels part the word splits along the\r\n            midline and what was behind it arrives &mdash; no duplicate assets, no measuring.</p>\r\n          <ul class=\"spec mono rv\">\r\n            <li>Two clipping halves</li><li>One word, two draws</li>\r\n            <li>Reveals behind</li><li>Scrubbed</li>\r\n          </ul>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"pin\" data-pin>\r\n      <div class=\"pin-stage\">\r\n        <canvas class=\"pin-bg\" data-bg=\"aurora\" data-density=\".9\" data-speed=\".8\" data-alpha=\".9\" data-seed=\"5\" aria-hidden=\"true\"></canvas>\r\n        <span class=\"pin-veil\" aria-hidden=\"true\"></span>\r\n\r\n        <div class=\"sp2-behind\">\r\n          <div class=\"wrap\">\r\n            <h3>Design, search and infrastructure.</h3>\r\n            <p>The three disciplines behind every build we ship, and the reason a Digital Treasury\r\n              project does not stall at the handover.</p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"sp2\" aria-hidden=\"true\">\r\n          <div class=\"sp2-half t\"><span class=\"sp2-word\">TREASURY</span></div>\r\n          <div class=\"sp2-half b\"><span class=\"sp2-word\">TREASURY</span></div>\r\n        </div>\r\n\r\n        <p class=\"pin-meter\"><span>Aperture</span><span class=\"bar\"><i></i></span><b data-k-out=\"pct\">000</b></p>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- ============ 03 — WORD CASCADE ============ -->\r\n  <section class=\"lab-sec\" id=\"cascade\" style=\"padding-bottom:0\">\r\n    <div class=\"wrap\">\r\n      <div class=\"lab-head\">\r\n        <div>\r\n          <p class=\"mono eyebrow rv\">Set-piece 03 &middot; Word cascade</p>\r\n          <h2 class=\"display\" data-split=\"rise\">One word at a time.</h2>\r\n        </div>\r\n        <div>\r\n          <p class=\"lede rv\">Each word carries its own offset into the same scrubbed value and\r\n            mixes from the dim ink to the bright accent as the scroll passes it. The paragraph is\r\n            still a paragraph in the accessibility tree &mdash; only the visible layer is split.</p>\r\n          <ul class=\"spec mono rv\">\r\n            <li>Per-word offset</li><li>color-mix in oklab</li>\r\n            <li>Real sentence for readers</li><li>No opacity stacking</li>\r\n          </ul>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"pin\" data-pin>\r\n      <div class=\"pin-stage\">\r\n        <canvas class=\"pin-bg\" data-bg=\"ledger\" data-density=\".7\" data-speed=\".7\" data-alpha=\".5\" aria-hidden=\"true\"></canvas>\r\n        <span class=\"pin-veil\" aria-hidden=\"true\"></span>\r\n        <div class=\"wrap\">\r\n          <div class=\"wc\">\r\n            <p data-words data-em=\"earn\" data-spread=\"0.8\">A website is not a brochure. It is the\r\n              one asset that works while nobody is watching, and it has to earn its place against\r\n              the number you started with.</p>\r\n          </div>\r\n        </div>\r\n        <p class=\"pin-meter\"><span>Cascade</span><span class=\"bar\"><i></i></span><b data-k-out=\"pct\">000</b></p>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- ============ 04 — HORIZONTAL PAN ============ -->\r\n  <section class=\"lab-sec\" id=\"pan\" style=\"padding-bottom:0\">\r\n    <div class=\"wrap\">\r\n      <div class=\"lab-head\">\r\n        <div>\r\n          <p class=\"mono eyebrow rv\">Set-piece 04 &middot; Horizontal pan</p>\r\n          <h2 class=\"display\" data-split=\"rise\">Down the page, across the work.</h2>\r\n        </div>\r\n        <div>\r\n          <p class=\"lede rv\">Vertical scroll driving horizontal travel. The overshoot is\r\n            <code>100vw - 100%</code> of the track itself, so the pan always ends exactly on the\r\n            last card whatever is in it &mdash; nothing measured, nothing to go stale on resize.</p>\r\n          <ul class=\"spec mono rv\">\r\n            <li>Pure CSS distance</li><li>No measurement</li>\r\n            <li>Ends flush</li><li>Scrollable under reduced motion</li>\r\n          </ul>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"pin\" data-pin style=\"height:300vh\">\r\n      <div class=\"pin-stage\">\r\n        <canvas class=\"pin-bg\" data-bg=\"streaks\" data-density=\"1\" data-speed=\"1.2\" data-alpha=\".6\" aria-hidden=\"true\"></canvas>\r\n        <span class=\"pin-veil\" aria-hidden=\"true\"></span>\r\n\r\n        <div class=\"hp-head\">\r\n          <span class=\"mono k\">Selected work</span>\r\n          <h3>Eleven years of it.</h3>\r\n        </div>\r\n\r\n        <div class=\"hp-rail\">\r\n          <div class=\"hp-track\">\r\n            <figure class=\"hp-c\"><img src=\"https://cdn.prod.website-files.com/662b4731a3ded1e03b5c4ba8/67ca5149dc641e09321517c1_EHG-p-800.png\" alt=\"Education Horizons\" loading=\"lazy\" decoding=\"async\"><figcaption><span>Education Horizons</span><em>2025</em></figcaption></figure>\r\n            <figure class=\"hp-c\"><img src=\"https://cdn.jsdelivr.net/gh/Alexander-DT/dt-craft@v1.11.0/img/neon.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"><figcaption><span>Signal</span><em>Study</em></figcaption></figure>\r\n            <figure class=\"hp-c\"><img src=\"https://cdn.prod.website-files.com/662b4731a3ded1e03b5c4ba8/67ca5a9ca7c9932f9ae33e36_MePACS-p-800.png\" alt=\"MePACS\" loading=\"lazy\" decoding=\"async\"><figcaption><span>MePACS</span><em>2024</em></figcaption></figure>\r\n            <figure class=\"hp-c\"><img src=\"https://cdn.jsdelivr.net/gh/Alexander-DT/dt-craft@v1.11.0/img/forms.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"><figcaption><span>Forms</span><em>Render</em></figcaption></figure>\r\n            <figure class=\"hp-c\"><img src=\"https://cdn.prod.website-files.com/662b4731a3ded1e03b5c4ba8/67ca6cd29941ed286c5f380b_RTO%20Pilot-p-800.png\" alt=\"RTOPilot\" loading=\"lazy\" decoding=\"async\"><figcaption><span>RTOPilot</span><em>2026</em></figcaption></figure>\r\n            <figure class=\"hp-c\"><img src=\"https://cdn.jsdelivr.net/gh/Alexander-DT/dt-craft@v1.11.0/img/botanical.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"><figcaption><span>Botanical</span><em>Field</em></figcaption></figure>\r\n            <figure class=\"hp-c\"><img src=\"https://cdn.prod.website-files.com/662b4731a3ded1e03b5c4ba8/682d8ca0f216d25240398269_Airpin%20(1)-p-800.png\" alt=\"Airpin\" loading=\"lazy\" decoding=\"async\"><figcaption><span>Airpin</span><em>2025</em></figcaption></figure>\r\n            <figure class=\"hp-c\"><img src=\"https://cdn.prod.website-files.com/662b4731a3ded1e03b5c4ba8/68db76d42662f92f1a556b73_D2C%20(1)-p-800.png\" alt=\"Desert to Coast\" loading=\"lazy\" decoding=\"async\"><figcaption><span>Desert to Coast</span><em>2026</em></figcaption></figure>\r\n            <figure class=\"hp-c\"><img src=\"https://cdn.jsdelivr.net/gh/Alexander-DT/dt-craft@v1.11.0/img/ridge.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"><figcaption><span>Ridge line</span><em>Field</em></figcaption></figure>\r\n          </div>\r\n        </div>\r\n\r\n        <p class=\"pin-meter\"><span>Travel</span><span class=\"bar\"><i></i></span><b data-k-out=\"pct\">000</b></p>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- ============ 05 — CINEMATIC COUNTER ============ -->\r\n  <section class=\"lab-sec\" id=\"counter\" style=\"padding-bottom:0\">\r\n    <div class=\"wrap\">\r\n      <div class=\"lab-head\">\r\n        <div>\r\n          <p class=\"mono eyebrow rv\">Set-piece 05 &middot; Cinematic counter</p>\r\n          <h2 class=\"display\" data-split=\"rise\">Count in, then hand over.</h2>\r\n        </div>\r\n        <div>\r\n          <p class=\"lede rv\">A number counting to a hundred while the frame behind it un-dims and\r\n            settles out of an over-scale, then the number stands down and the lines take over &mdash;\r\n            each on its own offset. Title sequence pacing, entirely on the scrollbar.</p>\r\n          <ul class=\"spec mono rv\">\r\n            <li>Counter tied to scrub</li><li>Over-scale settle</li>\r\n            <li>Staggered line masks</li><li>Hands off at 58%</li>\r\n          </ul>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"pin\" data-pin style=\"height:280vh\">\r\n      <div class=\"pin-stage\">\r\n        <div class=\"cin-shot\" aria-hidden=\"true\">\r\n          <img src=\"https://cdn.prod.website-files.com/662b4731a3ded1e03b5c4ba8/67ca6cd29941ed286c5f380b_RTO%20Pilot-p-1600.png\" alt=\"\" loading=\"lazy\" decoding=\"async\">\r\n        </div>\r\n        <div class=\"wrap\">\r\n          <div class=\"cin\">\r\n            <p class=\"cin-num\" aria-hidden=\"true\"><span data-k-out=\"pct\" data-k-max=\"100\" data-k-pad=\"3\">000</span></p>\r\n            <div class=\"cin-lines\">\r\n              <span class=\"cin-l\" style=\"--th:.34\"><span>Design, search</span></span>\r\n              <span class=\"cin-l\" style=\"--th:.44\"><span>and infrastructure</span></span>\r\n              <span class=\"cin-l\" style=\"--th:.54\"><span>under one roof.</span></span>\r\n            </div>\r\n          </div>\r\n        </div>\r\n        <p class=\"pin-meter\"><span>Sequence</span><span class=\"bar\"><i></i></span><b data-k-out=\"pct\">000</b></p>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- ============ 06 — DEPTH FLIGHT ============ -->\r\n  <section class=\"lab-sec\" id=\"depth\" style=\"padding-bottom:0\">\r\n    <div class=\"wrap\">\r\n      <div class=\"lab-head\">\r\n        <div>\r\n          <p class=\"mono eyebrow rv\">Set-piece 06 &middot; Depth flight</p>\r\n          <h2 class=\"display\" data-split=\"rise\">Through, not past.</h2>\r\n        </div>\r\n        <div>\r\n          <p class=\"lede rv\">Three planes scaling at very different rates, each fading as it passes\r\n            the camera. Scale alone reads as distance when the rates are far enough apart &mdash;\r\n            no perspective, no 3D context, nothing that would take the page out of the compositor.</p>\r\n          <ul class=\"spec mono rv\">\r\n            <li>Rates 0.5 / 1.6 / 4.2</li><li>Staggered fade-out</li>\r\n            <li>Transform + opacity only</li><li>Copy lands last</li>\r\n          </ul>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"pin\" data-pin>\r\n      <div class=\"pin-stage\">\r\n        <canvas class=\"pin-bg\" data-bg=\"starfield\" data-density=\"1.3\" data-speed=\"1.4\" data-alpha=\".9\" data-seed=\"77\" aria-hidden=\"true\"></canvas>\r\n\r\n        <div class=\"df\" aria-hidden=\"true\">\r\n          <div class=\"df-l\" style=\"--rate:.5;--out:.86\"><span class=\"ring\"></span></div>\r\n          <div class=\"df-l\" style=\"--rate:1.6;--out:.7\"><span class=\"plate\"><img src=\"https://cdn.jsdelivr.net/gh/Alexander-DT/dt-craft@v1.11.0/img/forest-lake.jpg\" alt=\"\" loading=\"lazy\" decoding=\"async\"></span></div>\r\n          <div class=\"df-l\" style=\"--rate:4.2;--out:.5\"><span class=\"ring\"></span></div>\r\n        </div>\r\n\r\n        <div class=\"wrap\">\r\n          <div class=\"df-copy\">\r\n            <h3>The craft layer is the difference.</h3>\r\n            <p>Between a site that looks good in a screenshot and one that is worth scrolling\r\n              twice. It is also the part that moves the price band.</p>\r\n          </div>\r\n        </div>\r\n\r\n        <p class=\"pin-meter\"><span>Depth</span><span class=\"bar\"><i></i></span><b data-k-out=\"pct\">000</b></p>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n\r\n  <!-- ============ 07 — SCROLL ROTATION ============ -->\r\n  <section class=\"lab-sec\" id=\"rotation\" style=\"padding-bottom:0\">\r\n    <div class=\"wrap\">\r\n      <div class=\"lab-head\">\r\n        <div>\r\n          <p class=\"mono eyebrow rv\">Set-piece 07 &middot; Scroll rotation</p>\r\n          <h2 class=\"display\" data-split=\"rise\">The die turns.</h2>\r\n        </div>\r\n        <div>\r\n          <p class=\"lede rv\">The plate rotates with the scroll and every mark around its rim\r\n            counter-rotates by exactly the same amount, so the names stay upright while the disc\r\n            turns under them. That counter-rotation is the entire trick &mdash; without it you have\r\n            a wheel of sideways text.</p>\r\n          <ul class=\"spec mono rv\">\r\n            <li>320&deg; across the section</li><li>Rim marks counter-rotate</li>\r\n            <li>Radius measured, not guessed</li><li>Fixed index mark</li>\r\n          </ul>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"pin\" data-pin>\r\n      <div class=\"pin-stage\">\r\n        <canvas class=\"pin-bg\" data-bg=\"rings\" data-speed=\".4\" data-alpha=\".45\" aria-hidden=\"true\"></canvas>\r\n        <span class=\"pin-veil\" aria-hidden=\"true\"></span>\r\n\r\n        <div class=\"die\">\r\n          <div class=\"die-idx\" aria-hidden=\"true\"><i></i><span>At the die</span></div>\r\n          <div class=\"die-disc\" aria-hidden=\"true\"></div>\r\n          <div class=\"die-hub\" aria-hidden=\"true\"><b data-k-out=\"pct\" data-k-max=\"320\" data-k-pad=\"3\">000</b><em>Degrees turned</em></div>\r\n            <span class=\"die-m\"><i></i>Education Horizons</span>\r\n            <span class=\"die-m\"><i></i>MePACS</span>\r\n            <span class=\"die-m\"><i></i>RTOPilot</span>\r\n            <span class=\"die-m\"><i></i>Airpin</span>\r\n            <span class=\"die-m\"><i></i>Desert to Coast</span>\r\n            <span class=\"die-m\"><i></i>Diabetes Vic</span>\r\n            <span class=\"die-m\"><i></i>Brimbank</span>\r\n            <span class=\"die-m\"><i></i>TCW</span>\r\n        </div>\r\n\r\n        <p class=\"pin-meter\"><span>Rotation</span><span class=\"bar\"><i></i></span><b data-k-out=\"pct\">000</b></p>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- ============ 08 — SCROLL TICKER ============ -->\r\n  <section class=\"lab-sec\" id=\"ticker\" style=\"padding-bottom:0\">\r\n    <div class=\"wrap\">\r\n      <div class=\"lab-head\">\r\n        <div>\r\n          <p class=\"mono eyebrow rv\">Set-piece 08 &middot; Scroll ticker</p>\r\n          <h2 class=\"display\" data-split=\"rise\">Position, not a timer.</h2>\r\n        </div>\r\n        <div>\r\n          <p class=\"lede rv\">A looping band whose offset <em>is</em> the scrub. Scroll up and it\r\n            runs backwards immediately, which an animation on a timer cannot do &mdash; and the two\r\n            rows travel opposite ways, so the band never reads as one block sliding.</p>\r\n          <ul class=\"spec mono rv\">\r\n            <li>Offset = scroll</li><li>Reverses instantly</li>\r\n            <li>Duplicated strip</li><li>Two rows, opposed</li>\r\n          </ul>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"pin\" data-pin style=\"height:240vh\">\r\n      <div class=\"pin-stage\">\r\n        <canvas class=\"pin-bg\" data-bg=\"scan\" data-density=\".7\" data-speed=\".5\" data-alpha=\".45\" aria-hidden=\"true\"></canvas>\r\n        <span class=\"pin-veil\" aria-hidden=\"true\"></span>\r\n\r\n        <div class=\"sck\">\r\n          <div class=\"sck-row a\" aria-hidden=\"true\"><div class=\"strip\"><span>Design</span><span>Search</span><span>Platforms</span><span>Motion</span><span>Hosting</span><span>Melbourne</span></div></div>\r\n          <div class=\"sck-row b\" aria-hidden=\"true\"><div class=\"strip\"><span>Since 2015</span><span>Tier A craft</span><span>Fixed scope</span><span>Webflow</span><span>Headless</span><span>AUD</span></div></div>\r\n          <p class=\"sck-note\">Scroll either way &mdash; the band follows</p>\r\n        </div>\r\n\r\n        <p class=\"pin-meter\"><span>Offset</span><span class=\"bar\"><i></i></span><b data-k-out=\"pct\">000</b></p>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <section class=\"lab-sec\" id=\"next\">\r\n    <div class=\"wrap\" style=\"text-align:center\">\r\n      <p class=\"mono eyebrow rv\" style=\"justify-content:center\">One rig, six treatments</p>\r\n      <h2 class=\"display rv\" style=\"margin-bottom:26px\">Attach one per section.</h2>\r\n      <p class=\"lede rv\" style=\"margin:0 auto 32px\">Every set-piece above is a tall section carrying\r\n        <b style=\"color:var(--gold);font-weight:500\">data-pin</b> and a\r\n        <b style=\"color:var(--gold);font-weight:500\">.pin-stage</b> inside it. The module writes\r\n        one value; the treatment is CSS. Mixing three of these across a five-page site is what makes\r\n        it feel authored rather than assembled.</p>\r\n      <div class=\"rv\" style=\"display:flex;gap:12px;justify-content:center;flex-wrap:wrap\">\r\n        <a class=\"btn solid\" href=\"/backgrounds\" data-mag><span class=\"btn-l\">Backgrounds</span><span class=\"arw\">&#8594;</span></a>\r\n        <a class=\"btn\" href=\"/\" data-mag><span class=\"btn-l\">The homepage</span></a>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n</div></div>\r\n<div id=\"spacer\" aria-hidden=\"true\"></div>\n";
  var frag = document.createDocumentFragment();
  while (host.firstChild) frag.appendChild(host.firstChild);
  document.body.insertBefore(frag, document.body.firstChild);
})();
